floor_fn:
"""
    one-dimensional arrays having shape [N],
    row and column matrices having shape [1 N] and
    [N 1] correspondingly, and their generalizations
    having shape [1 1 ... N ... 1 1 1].
    Scalars have shape [1 1 ... 1].
    Empty arrays dont count
    """
def isvector_or_scalar_(a: Any) -> object {
    try {
        return (a.size and ((a.ndim - a.shape.count(1)) <= 1));
    } except Exception as e {
        return False;
    }
}

test_blocks:
test "t0" {
    assert (isvector_or_scalar_([[1, 2, 3], [1, 2, 3]]) == False);;
}

test "t1" {
    assert (isvector_or_scalar_(1) == False);;
}

test "t2" {
    assert (isvector_or_scalar_(["a", "b", "c"]) == False);;
}

test "t3" {
    assert (isvector_or_scalar_("") == False);;
}

test "t4" {
    assert (isvector_or_scalar_(`tuple()) == False);;
}

